import django.db.models.deletion
import re

from django.db import migrations, models


def vincular_cotizaciones(apps, schema_editor):
    """Las facturas creadas antes desde una cotización solo la mencionaban en las observaciones."""
    Documento = apps.get_model("core", "Documento")
    for factura in Documento.objects.filter(origen__isnull=True, tipo__in=(33, 34),
                                            observaciones__startswith="Según cotización N° "):
        numero = re.match(r"Según cotización N° (\d+)", factura.observaciones)
        if numero:
            cotizacion = Documento.objects.filter(
                sociedad_id=factura.sociedad_id, tipo=1, folio=int(numero.group(1))).first()
            if cotizacion:
                factura.origen = cotizacion
                factura.save(update_fields=["origen"])


